import 'dart:io';
import 'package:yaml/yaml.dart';

void main() {
  final pubspecFile = File('pubspec.yaml');
  if (!pubspecFile.existsSync()) {
    stderr.writeln('Error: pubspec.yaml not found.');
    exit(1);
  }

  final yamlDoc = loadYaml(pubspecFile.readAsStringSync()) as YamlMap;
  final version = yamlDoc['version'] as String;

  final targetFile = File('lib/src/version.dart');
  final content = '''// Generated version file. Do not edit directly.
// Generated by tool/update_version.dart or build scripts.
const String packageVersion = '$version';
''';

  targetFile.writeAsStringSync(content);
  print('Updated lib/src/version.dart with version: $version');
}
